const test=require('node:test'),assert=require('node:assert/strict'),dims=require('./garden-dimensions.json');
const modulePromise=import('../garden-farm.js');
test('garden layouts preserve normalized footprints, clear access and explicit semantics',async()=>{const m=await modulePromise;for(const seed of [41,73])for(const beds of [8,12])for(const layout of Object.keys(m.GARDEN_LAYOUTS)){const p=m.composeGarden({seed,beds,layout},dims),t=m.gardenTerrain(p.recipe);assert.equal(p.items.filter(o=>o.role==='bed').length,beds);assert.equal(p.routes.filter(r=>r.id.startsWith('access-')).length,p.items.length);assert(p.routes.some(r=>r.id.startsWith('aisle-')));assert(p.routes.filter(r=>r.from==='yard'&&r.to.startsWith('bed-')).length===0);for(const o of p.items){assert(o.purpose);assert.equal(o.simulation,'planned');for(const x of [-o.w/2,0,o.w/2])for(const z of [-o.d/2,0,o.d/2]){assert(m.inHex(o.x+x,o.z+z,2));assert(t.height(o.x+x,o.z+z)<=o.y+1e-8);}for(const q of p.items)if(q!==o)assert(Math.abs(q.x-o.x)>=(q.w+o.w)/2+1.19||Math.abs(q.z-o.z)>=(q.d+o.d)/2+1.19);}for(const r of p.routes)for(let i=1;i<r.points.length;i++){const a=r.points[i-1],b=r.points[i];for(let f=0;f<=1;f+=.2){const x=a.x+(b.x-a.x)*f,z=a.z+(b.z-a.z)*f;for(const o of p.items){if(r.to===o.id&&i===r.points.length-1)continue;assert(!(Math.abs(x-o.x)<o.w/2+r.width/2-.02&&Math.abs(z-o.z)<o.d/2+r.width/2-.02),`${layout}: ${r.id} intersects ${o.id}`);}}}assert.equal(p.interfaces[0].status,'candidate');assert(p.validation.unknown.length);}});
test('garden reconstruction is deterministic; carving does not move essential assets',async()=>{const m=await modulePromise,a=m.composeGarden({seed:41},dims),b=m.composeGarden({seed:41,carved:false},dims);assert.deepEqual(a.items,b.items);assert.deepEqual(a.routes,b.routes);assert.deepEqual(a,m.composeGarden(a.recipe,dims));const cut=m.clipHex([{x:-60,z:-60},{x:60,z:-60},{x:60,z:60},{x:-60,z:60}]);assert.equal(cut.length,6);assert(cut.every(p=>m.inHex(p.x,p.z)));assert.throws(()=>m.composeGarden({beds:9},dims));assert.throws(()=>m.composeGarden({}, {...dims,'garden-growing-plot':{w:100,d:100,h:1}}),/cannot fit/);});
